 "content": "from collections import deque


def transform(grid):
    """Reverse the color order of nested nonzero layers, component by component."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 0 or seen[sr][sc]:
                continue
            q = deque([(sr, sc)])
            seen[sr][sc] = True
            cells = []
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != 0:
                        seen[nr][nc] = True
                        q.append((nr,nc))
            bounds = {}
            for r, c in cells:
                color = grid[r][c]
                if color not in bounds:
                    bounds[color] = [r, r, c, c]
                else:
                    b = bounds[color]
                    b[0] = min(b[0], r); b[1] = max(b[1], r)
                    b[2] = min(b[2], c); b[3] = max(b[3], c)
            ordered = sorted(bounds, key=lambda color: (-(bounds[color][1]-bounds[color][0]+1)*(bounds[color][3]-bounds[color][2]+1), color))
            mapping = {old: new for old, new in zip(ordered, reversed(ordered))}
            for r, c in cells:
                out[r][c] = mapping[grid[r][c]]
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
